<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref,watch } from 'vue';
import { ApiError,request,transitions,type RecordItem,type Store } from './api';
import { WorkbenchDraft,emptyDraft,errorMessage,type Command } from './workbench';
const props=defineProps<{token:string;userId:string;tenantId:string;role:string;active?:boolean}>();
const emit=defineEmits<{locked:[boolean];busy:[boolean]}>();
const root=`/api/v1/merchant/tenants/${props.tenantId}`;
const draftStore=new WorkbenchDraft({getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v)},props.userId,props.tenantId);
const draft=ref(emptyDraft()),pending=ref<Command|null>(null),ready=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const store=ref<Store>({name:'',description:'',version:0}),rows=ref<RecordItem[]>([]),total=ref(0),page=ref(1),filter=ref('');
const day=ref(''),date=ref(''),method=ref(''),search=ref(''),overdue=ref(false),counts=ref<Record<string,number>>({}),asOf=ref(''),due=ref(''),copyNotice=ref(''),responseNote=ref('');
const detail=ref<RecordItem|null>(null),agreed=ref(false),note=ref(''),summary=ref(''),changeReason=ref(''),timeNote=ref('');
const labels:Record<string,string>={PENDING_CONFIRMATION:'待确认',CONFIRMED:'已确认',PREPARING:'备货中',READY:'待取/送',OUT_FOR_DELIVERY:'配送中',COMPLETED:'已完成',CANCELLED:'已取消'};
let alive=true,epoch=0,listGeneration=0,timer:ReturnType<typeof setTimeout>|undefined,delay=60000;
const contactPage=ref(1),contactTotal=ref(0);
const contactMethod=ref('PHONE'),contactNote=ref(''),contactConfirmed=ref(false),contactText=ref(''),contactReviewed=ref(false),contacts=ref<{id:string;method:string;note:string;created_at:string}[]>([]);
function contactLabel(method:string){return ({PHONE:'已电话联系',WECHAT:'已微信联系',NOT_REACHED:'暂未联系上'} as Record<string,string>)[method]||method;}
function clearContact(){contactPage.value=1;contactTotal.value=0;contactMethod.value='PHONE';contactNote.value='';contactConfirmed.value=false;contactText.value='';contactReviewed.value=false;contacts.value=[];}
function contactsPage(next:number){const row=detail.value;if(!row)return;return run(async()=>{const own=epoch;const result=await request<{items:typeof contacts.value;total:number}>(`${draftStore.root}/${row.id}/contacts?page=${next}`,props.token);if(safe()&&own===epoch){contacts.value=result.items;contactTotal.value=result.total;contactPage.value=next;}});}
function logContact(){const row=detail.value;if(!row||!contactConfirmed.value)return;return command(`${draftStore.root}/${row.id}/contacts`,{method:contactMethod.value,note:contactNote.value,confirmed:true,expected_version:row.version});}
function makeContactDraft(){const row=detail.value;if(!row)return;return run(async()=>{const own=epoch;const result=await request<{text:string}>(`${draftStore.root}/${row.id}/contact-draft`,props.token);if(safe()&&own===epoch){contactText.value=result.text;contactReviewed.value=false;}});}
function copyContact(){if(!contactReviewed.value)return;return run(async()=>{if(!navigator.clipboard){notice.value='当前环境不支持剪贴板，请手动选择摘要复制；尚未发送。';return;}await navigator.clipboard.writeText(contactText.value);if(safe())notice.value='已复制，请自行核对收件人后发送；未记录联系成功。';});}
const latest=computed(()=>detail.value?.confirmation_revisions?.at(-1));
watch(busy,x=>emit('busy',x),{immediate:true});watch(pending,x=>emit('locked',!!x),{immediate:true});
watch(draft,()=>{if(ready.value){try{draftStore.save(draft.value,pending.value);}catch(e){error.value=errorMessage(e);}}},{deep:true,flush:'sync'});
function safe(){return alive&&!document.hidden;}
async function run(action:()=>Promise<void>){if(busy.value||!safe())return;busy.value=true;error.value='';try{await action();}catch(e){if(safe())error.value=errorMessage(e);}finally{if(alive)busy.value=false;}}
function query(){const params=new URLSearchParams({page:String(page.value),limit:'20'});if(filter.value)params.set('status',filter.value);if(day.value)params.set('day',day.value);if(day.value==='date'&&date.value)params.set('on_date',date.value);if(method.value)params.set('method',method.value);if(search.value.trim())params.set('q',search.value.trim());if(overdue.value)params.set('overdue','true');return params.toString();}
async function list(){const own=epoch,version=++listGeneration;const [data,summary]=await Promise.all([request<{items:RecordItem[];total:number}>(`${root}/reservations?${query()}`,props.token),request<{counts:Record<string,number>;as_of:string}>(root+'/workbench-summary',props.token)]);if(safe()&&own===epoch&&version===listGeneration){rows.value=data.items;total.value=data.total;counts.value=summary.counts;asOf.value=summary.as_of;}}
function poll(){timer=setTimeout(async()=>{if(!alive)return;if(!document.hidden&&props.active!==false&&!busy.value&&!pending.value&&ready.value){try{await list();delay=60000;}catch{delay=Math.min(delay*2,300000);}}if(alive)poll();},delay);}
async function copy(row:RecordItem){if(pending.value||busy.value)return;if((draft.value.raw_text||draft.value.customer_label||draft.value.items.length)&&!window.confirm('当前有未保存草稿，确认用这条历史记录替换？'))return;return run(async()=>{const result=await request<{draft:ReturnType<typeof emptyDraft>;warnings:string[]}>(`${draftStore.root}/${row.id}/copy-draft`,props.token);if(!safe())return;draft.value={...emptyDraft(),...result.draft};draft.value.copy_review_required=true;copyNotice.value=result.warnings.join('；');notice.value='已复制到快速代记，请重新核对后保存；尚未创建新记录。';});}
function expected(event:Event){const value=(event.target as HTMLInputElement).value;draft.value.expected_at=value?new Date(value+':00+08:00').toISOString():null;}
function expectedInput(){return draft.value.expected_at?new Date(new Date(draft.value.expected_at).getTime()+8*3600000).toISOString().slice(0,16):'';}
function displayTime(value:string|null|undefined){return value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'未指定';}
async function storeRead(){const own=epoch;try{const value=await request<Store>(root+'/store',props.token);if(safe()&&own===epoch)store.value=value;}catch(e){if(!(e instanceof ApiError&&e.status===404))throw e;}}
function load(){return run(async()=>{ready.value=false;const saved=draftStore.read();draft.value=saved.draft;pending.value=saved.pending;ready.value=true;await storeRead();await list();});}
function refresh(next=1){if(busy.value)return;page.value=next;detail.value=null;agreed.value=false;return run(list);}
function open(row:RecordItem){return run(async()=>{const own=epoch;clearContact();detail.value=null;agreed.value=false;note.value='';responseNote.value='';summary.value='';changeReason.value='';timeNote.value='';due.value='';const [result,history]=await Promise.all([request<RecordItem>(`${root}/reservations/${row.id}`,props.token),request<{items:typeof contacts.value;total:number}>(`${root}/reservations/${row.id}/contacts`,props.token)]);if(safe()&&own===epoch){detail.value=result;contacts.value=history.items;contactTotal.value=history.total;}});}
function close(){clearContact();detail.value=null;agreed.value=false;note.value='';}
async function send(command:Command){
 const own=epoch;
 try{
  await request(command.path,props.token,'POST',command.body,command.key);
  if(!alive)return;
  // Persist clearing before unlocking; a storage failure retains the old same-key request.
  const next=command.path===draftStore.root?emptyDraft():draftStore.read().draft;
  draftStore.save(next,null);ready.value=false;draft.value=next;pending.value=null;ready.value=true;
  if(safe()&&own===epoch){copyNotice.value='';draft.value.copy_review_required=false;notice.value='已保存。可刷新列表核对最新处理结果。';close();page.value=1;try{await list();}catch{error.value='已保存，但列表刷新失败，请手动刷新；无需再次提交。';}}
 }catch(e){
  if(e instanceof ApiError&&e.status>=400&&e.status<500&&![401,403,408,429].includes(e.status)){
   draftStore.save(draft.value,null);pending.value=null;
  }
  throw e;
 }
}
function command(path:string,body:unknown){return run(async()=>{if(!ready.value||pending.value)return;const value={path,body,key:crypto.randomUUID()};draftStore.save(draft.value,value);pending.value=value;await send(value);});}
function create(){if(draft.value.copy_review_required||!draft.value.customer_label.trim()||!draft.value.raw_text.trim())return;const {media_ids:unused,copy_review_required:reviewed,...body}=draft.value as typeof draft.value&{media_ids?:unknown};return command(draftStore.root,body);}
function retry(){return run(async()=>{if(pending.value)await send(pending.value);});}
function transition(row:RecordItem,target:string){
 if(pending.value)return;
 const revision=row.confirmation_revisions?.at(-1);
 if(target==='CONFIRMED'&&revision&&(!detail.value||detail.value.id!==row.id||!agreed.value)){error.value='请先查看详情，核对最新确认内容并勾选已与顾客确认。';return;}
 return command(`${draftStore.root}/${row.id}/transitions`,{target_status:target,expected_version:row.version,note:note.value,visible_to_customer:false,...(target==='CONFIRMED'&&revision?{confirmation_revision_id:revision.id,customer_agreed:true}:{})});
}
function cancellation(decision:'ACCEPTED'|'REJECTED'){const row=detail.value,request=row?.cancellation_requests?.find(x=>x.status==='REQUESTED');if(!row||!request||!responseNote.value.trim())return;return command(`${draftStore.root}/${row.id}/cancellation-requests/${request.id}/decision`,{expected_version:row.version,decision,response_note:responseNote.value});}
function propose(){if(!detail.value||!summary.value.trim()||!changeReason.value.trim())return;return command(`${draftStore.root}/${detail.value.id}/confirmation-revisions`,{expected_version:detail.value.version,summary:summary.value,change_reason:changeReason.value,time_note:timeNote.value,fulfillment_at:due.value?new Date(due.value+':00+08:00').toISOString():null,items:[]});}
function saveStore(){return run(async()=>{const own=epoch;const value=store.value;const response=await request<Store>(root+'/store',props.token,'PUT',{name:value.name,description:value.description,expected_version:value.version,public_contact:value.public_contact||'',public_address:value.public_address||'',business_hours:value.business_hours||'',delivery_note:value.delivery_note||'',allow_pickup:!!value.allow_pickup,allow_delivery:!!value.allow_delivery,published:!!value.published});if(safe()&&own===epoch){store.value=response;notice.value='店铺资料已保存，Logo关联保持不变。';}});}
function visibility(){epoch++;if(document.hidden){clearContact();rows.value=[];detail.value=null;ready.value=false;draft.value=emptyDraft();store.value={name:'',description:'',version:0};}else if(!busy.value)void load();}
onMounted(()=>{document.addEventListener('visibilitychange',visibility);void load();poll();});
onUnmounted(()=>{if(timer)clearTimeout(timer);alive=false;epoch++;document.removeEventListener('visibilitychange',visibility);emit('locked',false);emit('busy',false);});
</script>
<template><div aria-label="商户日常工作台" :aria-busy="busy">
<p class="error" role="alert" v-if="error">{{error}}</p><p class="notice" role="status" v-if="notice">{{notice}}</p>
<p v-if="!ready&&!busy">工作台资料未就绪。<button @click="load">重新读取</button></p>
<section aria-label="快速代记"><h2>快速代记</h2><p>没有商品库也能先记下来。草稿仅保存在当前设备，按账号和店铺分别保存。</p>
<form @submit.prevent="create"><fieldset :disabled="busy||!!pending||!ready">
<label>顾客称呼<input v-model="draft.customer_label" required maxlength="100" placeholder="例如：陈阿姨，不自动关联顾客账号"></label>
<label>联系人<input v-model="draft.contact_name" maxlength="100" placeholder="仅用于本次联系，不绑定账号"></label><label>联系电话<input v-model="draft.contact_phone" maxlength="50" type="tel"></label><label v-if="draft.fulfillment_method==='DELIVERY'">配送地址<textarea v-model="draft.delivery_address" maxlength="500"></textarea></label>
<label>原始需求<textarea v-model="draft.raw_text" required maxlength="4000" placeholder="例如：半斤干贝分两袋，周三下午自提"></textarea></label>
<div class="row"><label>来源<select v-model="draft.source"><option value="MERCHANT_PHONE">电话</option><option value="MERCHANT_WECHAT">微信</option><option value="MERCHANT_IN_STORE">到店</option></select></label><label>交付意向<select v-model="draft.fulfillment_method"><option value="PICKUP">自提</option><option value="DELIVERY">商家配送</option></select></label></div>
<label>期望日期或时段<input v-model="draft.expected_time_note" maxlength="200" placeholder="保留顾客原话，不自动当成交付承诺"></label>
<label>顾客明确期望时间（北京时间，可空）<input type="datetime-local" :value="expectedInput()" @change="expected"></label>
<p v-if="copyNotice" class="notice">{{copyNotice}}</p><label v-if="copyNotice||draft.copy_review_required" class="check"><input type="checkbox" :checked="!draft.copy_review_required" @change="draft.copy_review_required=!($event.target as HTMLInputElement).checked">已重新核对数量、单位、规格、商品与交付时间</label>
<div v-for="(item,index) in draft.items" :key="index" class="row"><label>商品<input v-model="item.name" maxlength="120"></label><label>数量<input v-model="item.quantity" inputmode="decimal"></label><label>单位<input v-model="item.unit" maxlength="20"></label><label>规格<input v-model="item.spec" maxlength="120"></label><button type="button" @click="draft.items.splice(index,1)">移除此项</button></div>
<label>内部备注（顾客不可见）<textarea v-model="draft.internal_note" maxlength="2000"></textarea></label>
<label class="check"><input type="checkbox" v-model="draft.mark_confirmed">已通过电话等方式明确确认这条需求</label>
<button :disabled="draft.copy_review_required||!draft.customer_label.trim()||!draft.raw_text.trim()">保存需求</button></fieldset></form>
<p class="notice" v-if="pending">原操作结果待确认，暂不修改原内容。刷新页面并登录同一账号和店铺后仍可恢复。</p><button v-if="pending" :disabled="busy||!ready" @click="retry">重试原提交</button>
</section>
<section aria-label="待办概览"><h2>本店待办</h2><div class="actions"><button v-for="status in ['PENDING_CONFIRMATION','CONFIRMED','PREPARING','READY','OUT_FOR_DELIVERY']" :key="status" :disabled="busy" @click="filter=status;refresh()">{{labels[status]}} {{counts[status]||0}}</button><button :disabled="busy" @click="overdue=!overdue;refresh()">已逾承诺时间 {{counts.OVERDUE||0}}</button></div><p>待回复询货 {{counts.NEW_INQUIRY||0}} · 待处理取消 {{counts.CANCELLATION_REQUESTED||0}}（打开记录详情处理；询货入口在原生工作台）</p><small>统计更新：{{displayTime(asOf)}}。页面可见时约每分钟刷新，失败退避至五分钟；不是微信消息通知。</small></section>
<section aria-label="待办与历史"><form class="row" @submit.prevent="refresh()"><label>按日期<select v-model="day" :disabled="busy"><option value="">所有日期</option><option value="today">今天</option><option value="tomorrow">明天</option><option value="date">指定日期</option><option value="none">未指定时间</option></select></label><label v-if="day==='date'">指定日期（北京时间）<input v-model="date" type="date" required></label><label>交付方式<select v-model="method"><option value="">全部</option><option value="PICKUP">自提</option><option value="DELIVERY">配送</option></select></label><label>本店历史搜索<input v-model="search" maxlength="100" placeholder="顾客称呼、需求文字、LS业务号"></label><label class="check"><input type="checkbox" v-model="overdue">仅已逾商户承诺时间</label><button :disabled="busy">应用筛选</button></form><p class="muted">日期优先采用已确认承诺时间，其次顾客明确期望时间；文字时段不猜日期。逾期只按已确认的精确承诺，排除完成和取消。</p><div class="row"><h2>待办与历史（{{total}}）</h2><label>状态<select v-model="filter" :disabled="busy" @change="refresh()"><option value="">全部</option><option v-for="(label,status) in labels" :key="status" :value="status">{{label}}</option></select></label><button :disabled="busy||!ready" @click="refresh(page)">刷新待办</button></div>
<p class="empty" v-if="!rows.length&&!busy&&!error">当前筛选没有记录。可以先用上面的快速代记保存第一条需求。</p>
<article v-for="row in rows" :key="row.id"><div class="row"><strong>{{row.customer_label}}</strong><span class="badge">{{labels[row.status]}}</span></div><small>{{row.business_number}}</small><p class="raw">{{row.raw_text}}</p><p v-if="row.is_overdue" class="error">已逾承诺时间 {{displayTime(row.confirmed_due_at)}}</p><small>{{row.fulfillment_method==='PICKUP'?'自提':'配送'}} · 版本 {{row.version}}</small>
<div class="actions"><button class="secondary" :disabled="busy" @click="open(row)">查看详情与历史</button><button :disabled="busy||!!pending" @click="copy(row)">复制为新需求</button><button v-for="target in transitions(row)" :key="target" :disabled="busy||!!pending" @click="transition(row,target)">{{labels[target]}}</button></div></article>
<div class="row"><button :disabled="busy||page<=1" @click="refresh(page-1)">上一页</button><span>第 {{page}} 页</span><button :disabled="busy||page*20>=total" @click="refresh(page+1)">下一页</button></div></section>
<section v-if="detail" aria-label="处理详情"><button class="secondary" @click="close">关闭详情</button><h2>{{detail.customer_label}} · {{labels[detail.status]}}</h2><p>{{detail.business_number}} · {{detail.contact_name}} {{detail.contact_phone}}</p><p v-if="detail.delivery_address">配送地址：{{detail.delivery_address}}</p><p>已确认承诺时间：{{displayTime(detail.confirmed_due_at)}}</p><h3>原始需求（保留不改）</h3><p class="raw">{{detail.raw_text}}</p><p>顾客期望：{{detail.expected_time_note||'未填写'}}</p><p v-if="detail.internal_note" class="notice">内部备注（顾客不可见）：{{detail.internal_note}}</p>
<ul v-if="detail.items?.length"><li v-for="(item,i) in detail.items" :key="i">{{item.name}} · {{item.quantity}} {{item.unit}} · {{item.spec}}</li></ul>
<template v-if="latest"><h3>最新确认候选</h3><p class="raw">{{latest.details.summary}}</p><p>{{latest.details.time_note||'未填写确认时间备注'}}</p><label v-if="detail.status==='PENDING_CONFIRMATION'" class="check"><input type="checkbox" v-model="agreed" :disabled="busy||!!pending">已与顾客核对并确认以上最新内容</label></template>
<section v-if="detail.cancellation_requests?.some(x=>x.status==='REQUESTED')" aria-label="取消申请处理"><h3>顾客申请取消，尚未取消</h3><p v-for="cancel in detail.cancellation_requests?.filter(x=>x.status==='REQUESTED')" :key="cancel.id">{{cancel.reason}}</p><label>给顾客的处理说明<input v-model="responseNote" maxlength="500" :disabled="busy||!!pending"></label><div class="actions"><button :disabled="busy||!!pending||!responseNote.trim()" @click="cancellation('ACCEPTED')">明确同意取消</button><button :disabled="busy||!!pending||!responseNote.trim()" @click="cancellation('REJECTED')">说明原因并拒绝取消</button></div></section>
<label>本次内部处理备注<input v-model="note" maxlength="500" :disabled="busy||!!pending"></label><div class="actions"><button v-for="target in transitions(detail)" :key="target" :disabled="busy||!!pending" @click="transition(detail!,target)">{{labels[target]}}</button></div>
<details v-if="['PENDING_CONFIRMATION','CONFIRMED'].includes(detail.status)&&!detail.cancellation_requests?.some(x=>x.status==='REQUESTED')"><summary>补充确认内容（保留原文，需重新确认）</summary><form @submit.prevent="propose"><fieldset :disabled="busy||!!pending"><label>确认内容<textarea v-model="summary" maxlength="4000" required></textarea></label><label>变更原因<input v-model="changeReason" maxlength="500" required></label><label>商户承诺交付时间（北京时间，可空）<input v-model="due" type="datetime-local"></label><label>确认时间备注<input v-model="timeNote" maxlength="200" placeholder="仅备注，不生成精确截止时间"></label><button>保存待确认候选</button></fieldset></form></details>
<section aria-label="人工联系记录"><h3>人工联系记录（仅商户可见）</h3><p>拨号、复制摘要或打开微信均不代表联系成功。请完成实际联系后明确登记结果。</p><form @submit.prevent="logContact"><fieldset :disabled="busy||!!pending"><label>联系结果<select v-model="contactMethod"><option value="PHONE">已电话联系</option><option value="WECHAT">已微信联系</option><option value="NOT_REACHED">暂未联系上</option></select></label><label>联系备注<textarea v-model="contactNote" maxlength="500"></textarea></label><label class="check"><input type="checkbox" v-model="contactConfirmed">确认这是实际联系后的结果</label><button :disabled="!contactConfirmed">保存联系结果</button></fieldset></form><ul><li v-for="contact in contacts" :key="contact.id">{{displayTime(contact.created_at)}} · {{contactLabel(contact.method)}} · {{contact.note}}</li></ul><button :disabled="busy||contactPage<=1" @click="contactsPage(contactPage-1)">上一页联系</button><button :disabled="busy||contactPage*50>=contactTotal" @click="contactsPage(contactPage+1)">下一页联系</button><button :disabled="busy||detail.status==='PENDING_CONFIRMATION'" @click="makeContactDraft">生成已确认需求联系摘要</button><template v-if="contactText"><label>待核对摘要<textarea readonly :value="contactText"></textarea></label><label class="check"><input type="checkbox" v-model="contactReviewed">已核对摘要内容和实际情况</label><button :disabled="busy||!contactReviewed" @click="copyContact">仅复制摘要</button></template></section><h3>处理历史</h3><ol><li v-for="(event,i) in detail.events" :key="i">{{labels[event.to_status]||event.action}}<span v-if="event.note">：{{event.note}}</span></li></ol></section>
<details class="store-settings"><summary>店铺资料与公开设置</summary><section><p>只有店主可保存；此处不会移除已关联的Logo。</p><button class="secondary" :disabled="busy||!ready" @click="run(storeRead)">重新读取店铺（放弃未保存修改）</button><form @submit.prevent="saveStore"><fieldset :disabled="busy||!!pending||role!=='OWNER'||!ready"><label>店名<input v-model="store.name" maxlength="100" required></label><label>店铺介绍<textarea v-model="store.description" maxlength="2000"></textarea></label><label>公开联系电话<input v-model="store.public_contact" maxlength="200"></label><label>公开地址<input v-model="store.public_address" maxlength="300"></label><label>营业时间<input v-model="store.business_hours" maxlength="200"></label><label>交付说明<textarea v-model="store.delivery_note" maxlength="500"></textarea></label><label class="check"><input type="checkbox" v-model="store.allow_pickup">允许自提</label><label class="check"><input type="checkbox" v-model="store.allow_delivery">允许商家配送</label><label class="check"><input type="checkbox" v-model="store.published">公开店铺资料与已发布商品</label><button :disabled="!store.name.trim()">保存店铺</button></fieldset></form></section></details>
<p class="muted">没有已验证的微信消息通知，请主动查看待办。这里只记录备货与交付，不涉及支付结算。</p>
</div></template>
